hcube = hypercube("indian_pines.dat");
gtLabel = load("indian_pines_gt.mat");
gtLabel = gtLabel.indian_pines_gt;
numClasses = 16;
band = [104:108 150:163 220]; % Water absorption bands
newhcube = removeBands(hcube,BandNumber=band);
rgbImg = colorize(newhcube,method="rgb");
%%
[~, ~, num_bands] = size(newhcube);

% Reshape the HSI data to 2D (pixels x bands)
hsi_reshaped = reshape(newhcube, [], num_bands);
%%
hsData = hsi_reshaped.DataCube;
hsi_normalized = zeros(size(hsData));
for band = 1:num_bands
    bandImage = hsData(:,:,band); 
    min_val = min(bandImage(:));
    max_val = max(bandImage(:));
    hsi_normalized(:,:,band) = (bandImage - min_val) / (max_val - min_val);
end
%%
% Center the data by subtracting the mean
hsData = hsi_reshaped.DataCube;
hsi_centered = zeros(size(hsData));
for band = 1:num_bands
    bandImage = hsData(:,:,band); 
    bandImageMean = mean(bandImage,1); 
    hsi_centered(:,:,band) = hsData(:,:,band) - bandImageMean;
end
%%
[pca_hs,~,~] = hyperpca(hsi_reshaped, 3, 'Method','Eig');
%%
figure %[output:8acaeafe]
rescalePC = rescale(pca_hs,0,1);
montage(rescalePC,'BorderSize',[10 10],'Size',[1 3]); %[output:2ee6883f] %[output:8acaeafe]
title('Principal Component Bands of Data Cube') %[output:8acaeafe]
%%
%[text] Wavelet Denoising
%%
[num_rows, num_cols, num_bands] = size(hsData);
wavelet_name = 'db1';  % Daubechies wavelet with 1 vanishing moment
decomposition_level = 2;  % Number of decomposition levels

% Initialize output denoised HSI
denoised_hsi_wd = zeros(num_rows, num_cols, num_bands);
%%
for band = 1:num_bands %[output:group:5eaf681c]
    % Extract the band
    band_data = hsData(:, :, band);
    
    % Perform 2D wavelet decomposition
    [C, S] = wavedec2(band_data, decomposition_level, wavelet_name) %[output:9168fa0c] %[output:06946b27]
    
    % Extract wavelet coefficients
    [H, V, D] = detcoef2('all', C, S, decomposition_level) %[output:1cf07997] %[output:99827fd1] %[output:57b9f87a]
    
    % Apply bivariate shrinkage thresholding
    % Compute threshold
    sigma = median(abs(H)) / 0.6745;  % Estimate noise standard deviation
    threshold = sigma * sqrt(2 * log(numel(band_data)));
    
    % Thresholding the coefficients
    H = bivariate_thresholding(H, threshold);
    V = bivariate_thresholding(V, threshold);
    D = bivariate_thresholding(D, threshold);
    
    % Reconstruct the denoised band
    A = appcoef2(C, S, wavelet_name, decomposition_level) %[output:4bd07dbc]
    A_col = reshape(A, [], 1);
    H_col = reshape(H, [], 1);
    V_col = reshape(V, [], 1);
    D_col = reshape(D, [], 1);
    c = [A_col  H_col V_col D_col] %[output:9fafdef9]
    s = [ %[output:0771c3c5]
    size(A);  % Size of approximation matrix %[output:0771c3c5]
    size(H);  % Size of horizontal detail matrix %[output:0771c3c5]
    size(V);  % Size of vertical detail matrix %[output:0771c3c5]
    size(D)   % Size of diagonal detail matrix %[output:0771c3c5]
    ] %[output:0771c3c5]
    denoised_band = waverec2(c, s, wavelet_name) %[output:923dfca7]
    
    % Store the denoised band
    denoised_hsi_wd(:, :, band) = denoised_band;
end %[output:group:5eaf681c]
% Bivariate thresholding function
function coeff = bivariate_thresholding(coeff, threshold)
    % Compute the magnitude
    magnitude = abs(coeff);
    
    % Apply the bivariate thresholding rule
    shrinkage_factor = max(0, 1 - threshold ./ (magnitude + eps));
    coeff = coeff .* shrinkage_factor;
end
%%

imagesc(denoised_hsi(:, :, 1));  % Display the first band
colormap(gray)
%%
%[text] LDA
%%
flattenedImages = reshape(pca_hs, [], 3)' %[output:84379d59]
labelFlattened  = reshape(gtLabel, 1, []) %[output:7d54ab24]
labelFlattened  =  %[output:3c6a6af7]
ldaModel = fitcdiscr(flattenedImages, labelFlattened) %[output:0a059635]
disp(ldaModel)
