%%
%hsData = hsi_reshaped.DataCube;
hsData = hsi_normalized %[output:137b2b44]
[M,N,C] = size(hsData);
denoised_hsi = zeros(size(hsData));
for band = 1:C
    bandImage = hsData(:,:,band); 
    bandImageFiltered = imgaussfilt(bandImage,2); 
    bandImageGray = mat2gray(bandImageFiltered);
    denoised_hsi(:,:,band) = uint8(bandImageGray*255);
end

[denoised_hsi_wd,coeff,var] = hyperpca(denoised_hsi, 3, 'Method','Eig');

figure %[output:91ea3081]
rescalePC = rescale(denoised_hsi_wd,0,1);
montage(rescalePC,'BorderSize',[10 10],'Size',[1 3]); %[output:91ea3081]
title('Principal Component Bands of Data Cube After PCA') %[output:91ea3081]
%%
%[text] Total Variation Denoising
%%
function u = tvdenoise(f, lambda, iter)
    % TVDENOISE Total Variation Denoising
    % f - Noisy input image
    % lambda - Regularization parameter
    % iter - Number of iterations

    [m, n] = size(f);
    u = f;  % Initialize the denoised image
    px = zeros(m, n); % x-component of the dual field
    py = zeros(m, n); % y-component of the dual field
    tau = 0.25; % Step size

    for i = 1:iter
        % Compute gradient of u
        ux = [diff(u, 1, 2), u(:,1) - u(:,end)];
        uy = [diff(u, 1, 1); u(1,:) - u(end,:)];

        % Update dual variables
        px_new = px + tau * ux;
        py_new = py + tau * uy;
        norm_new = max(1, sqrt(px_new.^2 + py_new.^2));
        px = px_new ./ norm_new;
        py = py_new ./ norm_new;

        % Update primal variable
        div_p = [px(:,end) - px(:,1), -diff(px, 1, 2)] + [py(end,:) - py(1,:); -diff(py, 1, 1)];
        u = f - lambda * div_p;
    end
end
%%
%hsData = hsi_normalized
hsData = hsi_reshaped.DataCube;
[M,N,C] = size(hsData);
denoised_hsi_tv = zeros(size(hsData));
for band = 1:C
    bandImage = hsData(:,:,band); 
    denoised_hsi_tv(:,:,band) = tvdenoise(bandImage, 2, 200);
end
%%
[denoised_hsi_pca,coeff,var] = hyperpca(denoised_hsi, 3);
figure %[output:9d4fc6d8]
rescalePC = rescale(denoised_hsi_pca,0,1);
montage(rescalePC,'BorderSize',[10 10],'Size',[1 3]); %[output:9d4fc6d8]
title('Principal Component Bands of BLF Data Cube After PCA') %[output:9d4fc6d8]
%%
[M, N, C] = size(denoised_hsi_blf);
DataVector = reshape(denoised_hsi_blf,[M*N C]);
gtVector = gtLabel(:);

gtLocs = find(gtVector~=0);
classLabel = gtVector(gtLocs);
%%
per = 0.1; % Training percentage
cv = cvpartition(classLabel,HoldOut=1-per); %[output:132eddef]

%[text] 
locTrain = gtLocs(cv.training);
locTest = gtLocs(~cv.training);
%%
%[text] ## Classify Using SVM
%[text] Train the SVM classifier using the [fitcecoc](docid:stats_ug#bue3oc9) function.
svmMdl = fitcecoc(DataVector(locTrain,:),gtVector(locTrain,:));
%[text] Test the SVM classifier using the test data.
[svmLabelOut,~] = predict(svmMdl,DataVector(locTest,:));
%[text] ## Display Classification Results
%[text] Calculate and display the classification accuracy.
svmAccuracy = sum(svmLabelOut == gtVector(locTest))/numel(locTest);
disp(["Overall Classification Accuracy (%) = ",num2str(svmAccuracy.*100)]) %[output:42ee7a67]
%%
svmPredLabel = gtLabel;
svmPredLabel(locTest) = svmLabelOut;
%[text] Display the RGB image, ground truth map, and SVM classification map.
cmap = parula(numClasses);
figure %[output:6a1ee859]
montage({rgbImg,gtLabel,svmPredLabel},cmap,Size=[1 3],BorderSize=10) %[output:6a1ee859]
title("RGB Image | Ground Truth Map | SVM Classification Map (BLF)") %[output:6a1ee859]
% Specify the intensity limits for the colorbar
minR = min(min(gtLabel(:)),min(svmPredLabel(:)));
maxR = max(max(gtLabel(:)),max(svmPredLabel(:)));
clim([minR maxR]) %[output:6a1ee859]
colorbar %[output:6a1ee859]
